class Solution {
    public boolean isMatch(String s, String p) {
        int m = s.length();
        int n = p.length();
        boolean[][] dp = new boolean[m + 1][n + 1];
        dp[0][0] = true;
        for (int j = 1; j <= n; j++) {
            if (p.charAt(j - 1) == '*') {
                dp[0][j] = dp[0][j - 1];
            }
        }
        for (int i = 1; i <= m; i++) {
            for (int j = 1; j <= n; j++) {
                char pc = p.charAt(j - 1);
                if (pc == '?' || pc == s.charAt(i - 1)) {
                    dp[i][j] = dp[i - 1][j - 1];
                } else if (pc == '*') {
                    dp[i][j] = dp[i][j - 1] || dp[i - 1][j];
                }
            }
        }
        return dp[m][n];
    }
}

class Solution {
    public boolean isMatch(String s, String p) {
        int m = s.length();
        int n = p.length();
        boolean[] previous = new boolean[n + 1];
        previous[0] = true;
        for (int j = 1; j <= n; j++) {
            if (p.charAt(j - 1) == '*') {
                previous[j] = previous[j - 1];
            }
        }
        for (int i = 1; i <= m; i++) {
            boolean[] current = new boolean[n + 1];
            for (int j = 1; j <= n; j++) {
                char pc = p.charAt(j - 1);
                if (pc == '*') {
                    current[j] = current[j - 1] || previous[j];
                } else if (pc == '?' || pc == s.charAt(i - 1)) {
                    current[j] = previous[j - 1];
                }
            }
            previous = current;
        }
        return previous[n];
    }
}

class Solution {
    public boolean isMatch(String s, String p) {
        int si = 0;
        int pi = 0;
        int starIndex = -1;
        int matchIndex = 0;
        while (si < s.length()) {
            if (pi < p.length() && (p.charAt(pi) == '?' || p.charAt(pi) == s.charAt(si))) {
                si++;
                pi++;
            } else if (pi < p.length() && p.charAt(pi) == '*') {
                starIndex = pi;
                matchIndex = si;
                pi++;
            } else if (starIndex != -1) {
                pi = starIndex + 1;
                matchIndex++;
                si = matchIndex;
            } else {
                return false;
            }
        }
        while (pi < p.length() && p.charAt(pi) == '*') {
            pi++;
        }
        return pi == p.length();
    }
}

class Solution {
    public boolean isMatch(String s, String p) {
        Boolean[][] memo = new Boolean[s.length() + 1][p.length() + 1];
        return dfs(0, 0, s, p, memo);
    }

    private boolean dfs(int i, int j, String s, String p, Boolean[][] memo) {
        if (memo[i][j] != null) {
            return memo[i][j];
        }
        if (j == p.length()) {
            memo[i][j] = i == s.length();
            return memo[i][j];
        }
        char pc = p.charAt(j);
        boolean answer;
        if (pc == '*') {
            answer = dfs(i, j + 1, s, p, memo)
                    || (i < s.length() && dfs(i + 1, j, s, p, memo));
        } else {
            answer = i < s.length()
                    && (pc == '?' || pc == s.charAt(i))
                    && dfs(i + 1, j + 1, s, p, memo);
        }
        memo[i][j] = answer;
        return answer;
    }
}
